// Takes an exclusive Web Lock named after lockPath and returns the function that releases it.
export function acquire(lockPath, { timeoutMs = 2_000 } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let release;
  const held = new Promise((resolve) => {
    release = resolve;
  });
  navigator.locks.request(lockPath, { mode: 'exclusive', signal: controller.signal }, () => held);
  clearTimeout(timer);
  return release;
}

