export function enqueue(type, payload = null, { delayMs = 0, maxAttempts, now = Date.now() } = {}) {
  if (!type) throw new Error('a job needs a type');
  const cfg = settings();
  return update((db) => {
    const job = {
      id: nextId(now),
      type,
      payload,
      state: STATES.PENDING,
      attempts: 0,
      maxAttempts: maxAttempts ?? cfg.maxAttempts,
      createdAt: now,
      runAt: now + delayMs,
      leaseUntil: null,
      worker: null,
      lastError: null,
    };
    db.jobs.push(job);
    return copy(job);
  });
}

